package com.raiddamagetracker;

import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

import javax.inject.Inject;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.util.*;
import java.util.List;

/**
 * Side panel — layout varies by DPS mode:
 *
 * BOSS_SPLIT
 * ┌─────────────────────────────┐
 * │ Raid Damage Tracker         │
 * │ Raid: Theatre of Blood      │
 * │                    [Reset]  │
 * ├─────────────────────────────┤
 * │ ▶ Maiden  (live)            │  ← NPC damage card (your dmg + %)
 * ├─────────────────────────────┤
 * │ DPS Log                     │
 * │  Maiden   1,823 dmg  3.12/s │  ← completed boss records
 * │  Bloat    2,011 dmg  4.55/s │
 * └─────────────────────────────┘
 *
 * RAID_OVERALL
 * ┌─────────────────────────────┐
 * │ Raid Damage Tracker         │
 * │ Raid: Chambers of Xeric     │
 * │ Overall DPS: 3.45           │
 * │ Total dmg:  9,124           │
 * │                    [Reset]  │
 * ├─────────────────────────────┤
 * │ ▶ Tekton  (live)            │
 * └─────────────────────────────┘
 */
public class RaidDamageTrackerPanel extends PluginPanel
{
    // Colours
    private static final Color HEADER_BG        = new Color(30, 30, 30);
    private static final Color SECTION_BG       = new Color(40, 40, 40);
    private static final Color ROW_BG_EVEN      = new Color(45, 45, 45);
    private static final Color ROW_BG_ODD       = new Color(50, 50, 50);
    private static final Color DEAD_COLOR       = new Color(180, 80,  80);
    private static final Color LIVE_COLOR       = new Color(80,  180, 80);
    private static final Color DPS_COLOR        = new Color(100, 200, 255);
    private static final Color GOLD             = new Color(255, 200, 80);
    private static final Color DIVIDER_COLOR    = new Color(60, 60, 60);
    private static final Color LOG_HEADER_BG    = new Color(35, 35, 35);

    private final RaidDamageTrackerConfig config;
    private RaidDamageTrackerPlugin plugin;   // set via setter after injection

    // ── Header widgets ────────────────────────────────────────────────────────
    private final JLabel raidLabel    = new JLabel("Not in a raid");
    private final JLabel overallDps   = new JLabel("Overall DPS: —");
    private final JLabel overallTotal = new JLabel("Total dmg: 0");
    private final JButton resetBtn    = new JButton("Reset");

    // ── Body ──────────────────────────────────────────────────────────────────
    private final JPanel contentPanel = new JPanel();

    // ── NPC cards (live + dead damage display) ────────────────────────────────
    /** npcKey → card component */
    private final Map<String, NpcCard> npcCards = new LinkedHashMap<>();

    // ── BOSS_SPLIT log section ────────────────────────────────────────────────
    private JPanel dpsLogSection;      // the whole section; rebuilt on each update
    private DpsMode currentMode = DpsMode.BOSS_SPLIT;

    @Inject
    public RaidDamageTrackerPanel(RaidDamageTrackerConfig config)
    {
        this.config = config;

        setLayout(new BorderLayout(0, 4));
        setBackground(ColorScheme.DARK_GRAY_COLOR);
        setBorder(new EmptyBorder(8, 8, 8, 8));

        add(buildHeader(), BorderLayout.NORTH);

        contentPanel.setLayout(new BoxLayout(contentPanel, BoxLayout.Y_AXIS));
        contentPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
        add(contentPanel, BorderLayout.CENTER);
    }

    /** Called by the plugin after construction so we can trigger hardReset from the button. */
    public void setPlugin(RaidDamageTrackerPlugin plugin)
    {
        this.plugin = plugin;
    }

    // ── Header ────────────────────────────────────────────────────────────────

    private JPanel buildHeader()
    {
        JPanel header = new JPanel();
        header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
        header.setBackground(HEADER_BG);
        header.setBorder(new EmptyBorder(8, 8, 8, 8));

        JLabel title = new JLabel("Raid Damage Tracker");
        title.setFont(FontManager.getRunescapeBoldFont());
        title.setForeground(Color.WHITE);
        title.setAlignmentX(LEFT_ALIGNMENT);

        styleSmall(raidLabel,    Color.LIGHT_GRAY);
        styleSmall(overallDps,   DPS_COLOR);
        styleSmall(overallTotal, Color.LIGHT_GRAY);

        resetBtn.setFont(FontManager.getRunescapeSmallFont());
        resetBtn.setForeground(Color.WHITE);
        resetBtn.setBackground(new Color(70, 30, 30));
        resetBtn.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createLineBorder(new Color(120, 50, 50)),
                new EmptyBorder(2, 8, 2, 8)));
        resetBtn.setFocusPainted(false);
        resetBtn.setAlignmentX(RIGHT_ALIGNMENT);
        resetBtn.addActionListener(e ->
        {
            if (plugin != null) plugin.hardReset();
        });

        // Reset row (right-aligned)
        JPanel resetRow = new JPanel(new FlowLayout(FlowLayout.RIGHT, 0, 0));
        resetRow.setBackground(HEADER_BG);
        resetRow.setAlignmentX(LEFT_ALIGNMENT);
        resetRow.add(resetBtn);

        header.add(title);
        header.add(Box.createVerticalStrut(4));
        header.add(raidLabel);
        header.add(overallDps);    // only visible in RAID_OVERALL mode
        header.add(overallTotal);  // only visible in RAID_OVERALL mode
        header.add(Box.createVerticalStrut(4));
        header.add(resetRow);

        return header;
    }

    private void styleSmall(JLabel label, Color fg)
    {
        label.setFont(FontManager.getRunescapeSmallFont());
        label.setForeground(fg);
        label.setAlignmentX(LEFT_ALIGNMENT);
    }

    // ── Public API (always called on EDT) ─────────────────────────────────────

    public void setRaid(RaidType type, DpsMode mode)
    {
        this.currentMode = mode;
        applyModeVisibility(mode);

        if (type == RaidType.NONE)
        {
            raidLabel.setText("Not in a raid");
            overallDps.setText("Overall DPS: —");
            overallTotal.setText("Total dmg: 0");
        }
        else
        {
            raidLabel.setText("Raid: " + type.getDisplayName()
                    + "  [" + mode.getDisplayName() + "]");
        }
        repaint();
    }

    public void reset()
    {
        npcCards.clear();
        contentPanel.removeAll();
        dpsLogSection = null;
        overallDps.setText("Overall DPS: —");
        overallTotal.setText("Total dmg: 0");
        contentPanel.revalidate();
        contentPanel.repaint();
    }

    // ── RAID_OVERALL ──────────────────────────────────────────────────────────

    public void updateOverallDps(int totalDamage, double dps)
    {
        overallDps.setText(String.format("Overall DPS: %.2f", dps));
        overallTotal.setText("Total dmg: " + formatDmg(totalDamage));
    }

    // ── BOSS_SPLIT ────────────────────────────────────────────────────────────

    /**
     * Rebuild the DPS log section at the bottom of the panel.
     * Called each time a boss dies with the full list of completed records.
     */
    public void setBossRecords(List<BossDpsRecord> records)
    {
        // Remove old section if present
        if (dpsLogSection != null)
        {
            contentPanel.remove(dpsLogSection);
        }

        dpsLogSection = buildDpsLogSection(records);
        contentPanel.add(dpsLogSection);
        contentPanel.revalidate();
        contentPanel.repaint();
    }

    private JPanel buildDpsLogSection(List<BossDpsRecord> records)
    {
        JPanel section = new JPanel();
        section.setLayout(new BoxLayout(section, BoxLayout.Y_AXIS));
        section.setBackground(SECTION_BG);
        section.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createLineBorder(DIVIDER_COLOR),
                new EmptyBorder(4, 6, 4, 6)));
        section.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));
        section.setAlignmentX(LEFT_ALIGNMENT);

        JLabel heading = new JLabel("DPS Log");
        heading.setFont(FontManager.getRunescapeBoldFont());
        heading.setForeground(DPS_COLOR);
        section.add(heading);
        section.add(Box.createVerticalStrut(4));

        // Column header
        section.add(buildLogRow("Boss", "Damage", "DPS", true));

        for (BossDpsRecord r : records)
        {
            section.add(buildLogRow(
                    r.bossName,
                    formatDmg(r.damage),
                    String.format("%.2f/s", r.getDps()),
                    false
            ));
        }

        return section;
    }

    private JPanel buildLogRow(String boss, String dmg, String dps, boolean header)
    {
        JPanel row = new JPanel(new GridBagLayout());
        row.setBackground(header ? LOG_HEADER_BG : ROW_BG_EVEN);
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 20));
        row.setAlignmentX(LEFT_ALIGNMENT);

        Font font  = header ? FontManager.getRunescapeBoldFont() : FontManager.getRunescapeSmallFont();
        Color fg   = header ? Color.WHITE : Color.LIGHT_GRAY;
        Color dpsFg = header ? Color.WHITE : DPS_COLOR;

        GridBagConstraints gc = new GridBagConstraints();
        gc.anchor = GridBagConstraints.WEST;
        gc.insets = new Insets(1, 3, 1, 3);

        gc.gridx = 0; gc.weightx = 1.0; gc.fill = GridBagConstraints.HORIZONTAL;
        JLabel bossL = new JLabel(boss); bossL.setFont(font); bossL.setForeground(fg);
        row.add(bossL, gc);

        gc.gridx = 1; gc.weightx = 0; gc.fill = GridBagConstraints.NONE;
        JLabel dmgL = new JLabel(dmg); dmgL.setFont(font); dmgL.setForeground(fg);
        row.add(dmgL, gc);

        gc.gridx = 2;
        JLabel dpsL = new JLabel(dps); dpsL.setFont(font); dpsL.setForeground(dpsFg);
        row.add(dpsL, gc);

        return row;
    }

    // ── Live NPC cards ────────────────────────────────────────────────────────

    /** Update the live card for a boss while it's still alive. */
    public void updateLiveNpc(String npcKey, int myDamage)
    {
        NpcCard card = npcCards.computeIfAbsent(npcKey, k ->
        {
            NpcCard c = new NpcCard(npcKey);
            // Insert before the DPS log section if present
            if (dpsLogSection != null)
            {
                int idx = getComponentIndex(contentPanel, dpsLogSection);
                contentPanel.add(c, idx >= 0 ? idx : contentPanel.getComponentCount());
            }
            else
            {
                contentPanel.add(c);
            }
            contentPanel.add(Box.createVerticalStrut(4));
            contentPanel.revalidate();
            return c;
        });
        card.update(myDamage, false);
        contentPanel.revalidate();
        contentPanel.repaint();
    }

    /** Mark a card as dead and freeze its damage total. */
    public void onNpcDied(String npcKey, int myDamage)
    {
        NpcCard card = npcCards.computeIfAbsent(npcKey, k ->
        {
            NpcCard c = new NpcCard(npcKey);
            contentPanel.add(c);
            contentPanel.add(Box.createVerticalStrut(4));
            contentPanel.revalidate();
            return c;
        });
        card.update(myDamage, true);
        contentPanel.revalidate();
        contentPanel.repaint();
    }

    // ── Helpers ───────────────────────────────────────────────────────────────

    private void applyModeVisibility(DpsMode mode)
    {
        boolean overall = (mode == DpsMode.RAID_OVERALL);
        overallDps.setVisible(overall);
        overallTotal.setVisible(overall);
    }

    private static int getComponentIndex(Container container, Component target)
    {
        for (int i = 0; i < container.getComponentCount(); i++)
        {
            if (container.getComponent(i) == target) return i;
        }
        return -1;
    }

    private static String formatDmg(int dmg)
    {
        return String.format("%,d", dmg);
    }

    // ── Inner class: NpcCard ─────────────────────────────────────────────────

    private class NpcCard extends JPanel
    {
        private final JLabel statusLabel;
        private final JLabel damageLabel;
        private final JLabel pctLabel;

        NpcCard(String npcKey)
        {
            setLayout(new BorderLayout(0, 2));
            setBackground(SECTION_BG);
            setBorder(BorderFactory.createCompoundBorder(
                    BorderFactory.createLineBorder(DIVIDER_COLOR),
                    new EmptyBorder(4, 6, 4, 6)));
            setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));
            setAlignmentX(LEFT_ALIGNMENT);

            String displayName = npcKey.contains(" #")
                    ? npcKey.substring(0, npcKey.lastIndexOf(" #"))
                    : npcKey;

            // ─ Title row ─
            JPanel titleRow = new JPanel(new BorderLayout());
            titleRow.setBackground(SECTION_BG);

            JLabel nameLabel = new JLabel(displayName);
            nameLabel.setFont(FontManager.getRunescapeBoldFont());
            nameLabel.setForeground(Color.WHITE);

            statusLabel = new JLabel("⚔ Alive");
            statusLabel.setFont(FontManager.getRunescapeSmallFont());
            statusLabel.setForeground(LIVE_COLOR);

            titleRow.add(nameLabel,   BorderLayout.WEST);
            titleRow.add(statusLabel, BorderLayout.EAST);
            add(titleRow, BorderLayout.NORTH);

            // ─ Damage row ─
            JPanel dmgRow = new JPanel(new GridBagLayout());
            dmgRow.setBackground(ROW_BG_EVEN);
            dmgRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 22));

            GridBagConstraints gc = new GridBagConstraints();
            gc.anchor = GridBagConstraints.WEST;
            gc.insets = new Insets(1, 3, 1, 3);

            JLabel youLabel = new JLabel("Your damage");
            youLabel.setFont(FontManager.getRunescapeSmallFont());
            youLabel.setForeground(GOLD);
            gc.gridx = 0; gc.weightx = 1.0; gc.fill = GridBagConstraints.HORIZONTAL;
            dmgRow.add(youLabel, gc);

            damageLabel = new JLabel("0");
            damageLabel.setFont(FontManager.getRunescapeSmallFont());
            damageLabel.setForeground(GOLD);
            gc.gridx = 1; gc.weightx = 0; gc.fill = GridBagConstraints.NONE;
            dmgRow.add(damageLabel, gc);

            pctLabel = new JLabel("");
            pctLabel.setFont(FontManager.getRunescapeSmallFont());
            pctLabel.setForeground(Color.GRAY);
            gc.gridx = 2;
            dmgRow.add(pctLabel, gc);

            add(dmgRow, BorderLayout.CENTER);
        }

        void update(int myDamage, boolean dead)
        {
            statusLabel.setText(dead ? "✗ Dead" : "⚔ Alive");
            statusLabel.setForeground(dead ? DEAD_COLOR : LIVE_COLOR);
            damageLabel.setText(formatDmg(myDamage));
            // Percentage doesn't apply when it's only your damage,
            // but keep the label in case we want to show % of boss HP in future.
            pctLabel.setText("");
        }
    }
}

package com.raiddamagetracker;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("raiddamagetracker")
public interface RaidDamageTrackerConfig extends Config
{
    @ConfigItem(
            keyName = "dpsMode",
            name = "DPS Mode",
            description = "<html><b>Per-Boss DPS:</b> logs your DPS for each boss individually when it dies; " +
                          "entries stay until you click Reset.<br>" +
                          "<b>Overall Raid DPS:</b> one running DPS counter for the whole raid; " +
                          "the timer pauses between boss rooms so lobby/transition time is excluded.</html>",
            position = 0
    )
    default DpsMode dpsMode()
    {
        return DpsMode.BOSS_SPLIT;
    }

    @ConfigItem(
            keyName = "showPercentages",
            name = "Show damage percentages",
            description = "Show your share of total damage as a percentage alongside the raw number",
            position = 1
    )
    default boolean showPercentages()
    {
        return true;
    }

    @ConfigItem(
            keyName = "showDeadNpcs",
            name = "Keep dead NPC entries",
            description = "Keep killed NPC damage summaries visible in the panel throughout the raid",
            position = 2
    )
    default boolean showDeadNpcs()
    {
        return true;
    }
}

package com.raiddamagetracker;

import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

import javax.inject.Inject;
import javax.swing.*;
import java.awt.image.BufferedImage;
import java.util.*;
import net.runelite.api.events.GameTick;

@Slf4j
@PluginDescriptor(
        name = "Raid Damage Tracker",
        description = "Tracks your damage on each boss in CoX, ToB, and ToA raids with configurable DPS modes",
        tags = {"raid", "damage", "tracker", "cox", "tob", "toa", "dps", "chambers", "theatre", "tombs"}
)
public class RaidDamageTrackerPlugin extends Plugin
{
    // -------------------------------------------------------------------------
    // Raid region IDs
    // -------------------------------------------------------------------------
    private static final int COX_REGION       = 12889;
    private static final int COX_LOBBY_REGION = 12890;
    private static final int TOB_REGION       = 12611;
    private static final int TOB_LOBBY_REGION = 14642;
    private static final int TOA_REGION       = 14160;
    private static final int TOA_LOBBY_REGION = 13454;

    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private ClientToolbar clientToolbar;
    @Inject private RaidDamageTrackerConfig config;

    private RaidDamageTrackerPanel panel;
    private NavigationButton navButton;

    // -------------------------------------------------------------------------
    // Raid state
    // -------------------------------------------------------------------------
    private RaidType currentRaid = RaidType.NONE;

    /**
     * Per-NPC damage tracking (your hits only).
     * Key: "NpcName #index"  Value: total damage you dealt
     */
    private final Map<String, Integer> damageByNpc = new LinkedHashMap<>();

    /** Maps NPC index → canonical key so we can look up on hitsplat/despawn. */
    private final Map<Integer, String> npcKeys = new HashMap<>();

    // -------------------------------------------------------------------------
    // BOSS_SPLIT mode state
    // -------------------------------------------------------------------------

    /**
     * For each tracked NPC, the time (ms) we first dealt damage to it.
     * Used as the start of the boss fight window for DPS calculation.
     */
    private final Map<Integer, Long> bossFirstHitTime = new HashMap<>();

    /**
     * Completed boss DPS records, in kill order.
     * Persists until the user clicks "Reset" in the panel.
     */
    private final List<BossDpsRecord> bossRecords = new ArrayList<>();

    // -------------------------------------------------------------------------
    // RAID_OVERALL mode state
    // -------------------------------------------------------------------------

    /**
     * Total damage dealt to all bosses across the raid (your hits only).
     * Resets when a new raid starts or user hits Reset.
     */
    private int overallTotalDamage = 0;

    /**
     * Accumulated active-combat milliseconds.
     * The timer runs only while at least one tracked boss is alive in the room
     * (i.e. in npcKeys), so inter-room transitions don't inflate the denominator.
     */
    private long overallAccumulatedMs = 0;

    /**
     * Timestamp (ms) when the current combat window started, or -1 if paused.
     * Set to System.currentTimeMillis() when the first boss spawns in a room;
     * set to -1 when the last tracked boss in the room despawns.
     */
    private long overallCombatWindowStart = -1;

    // -------------------------------------------------------------------------

    @Override
    protected void startUp()
    {
        panel = injector.getInstance(RaidDamageTrackerPanel.class);
        panel.setPlugin(this);   // needed so the Reset button can call hardReset()

        final BufferedImage icon = ImageUtil.loadImageResource(
                getClass(), "/com/raiddamagetracker/icon.png");

        navButton = NavigationButton.builder()
                .tooltip("Raid Damage Tracker")
                .icon(icon)
                .priority(6)
                .panel(panel)
                .build();

        clientToolbar.addNavigation(navButton);
        log.info("Raid Damage Tracker started");
    }

    @Override
    protected void shutDown()
    {
        clientToolbar.removeNavigation(navButton);
        hardReset();
        log.info("Raid Damage Tracker stopped");
    }

    @Provides
    RaidDamageTrackerConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(RaidDamageTrackerConfig.class);
    }

    // -------------------------------------------------------------------------
    // Region / raid detection
    // -------------------------------------------------------------------------

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOADING)
        {
            updateRaidType();
        }
    }

    private void updateRaidType()
    {
        if (client.getLocalPlayer() == null) return;

        int region = client.getLocalPlayer().getWorldLocation().getRegionID();
        RaidType detected = RaidType.NONE;

        // Use varbits for reliable raid detection across all worlds including Leagues
        // Varbit 5424 = CoX raid state (1+ = in raid)
        // Varbit 6447 = ToB raid state (1+ = in raid)
        // Varbit 14345 = ToA raid state (1+ = in raid)
        int coxVarbit  = client.getVarbitValue(5424);
        int tobVarbit  = client.getVarbitValue(6447);
        int toaVarbit  = client.getVarbitValue(14345);

        if      (coxVarbit > 0) detected = RaidType.COX;
        else if (tobVarbit > 0) detected = RaidType.TOB;
        else if (toaVarbit > 0) detected = RaidType.TOA;

        //log.info("updateRaidType:",

        if (detected == currentRaid) return;

        if (detected != RaidType.NONE)
        {
            startRaid(detected);
        }
        else
        {
            endRaid();
        }
        currentRaid = detected;
    }

    private void startRaid(RaidType type)
    {
        damageByNpc.clear();
        npcKeys.clear();
        bossFirstHitTime.clear();
        bossRecords.clear();
        overallTotalDamage = 0;
        overallAccumulatedMs = 0;
        overallCombatWindowStart = -1;
        currentRaid = type;
        SwingUtilities.invokeLater(() -> { panel.reset(); panel.setRaid(type, config.dpsMode()); });
        log.info("Entered raid: {}", type);

        // Scan for already-alive bosses on the client thread
        clientThread.invokeLater(() ->
        {
            if (client.getNpcs() == null) return;
            for (NPC npc : client.getNpcs())
            {
                if (npc == null) continue;
                if (!isTrackedNpc(npc)) continue;
                String key = npcKey(npc);
                npcKeys.put(npc.getIndex(), key);
                damageByNpc.put(key, 0);
                SwingUtilities.invokeLater(() -> panel.updateLiveNpc(key, 0));
            }
            if (config.dpsMode() == DpsMode.RAID_OVERALL && !npcKeys.isEmpty())
            {
                overallCombatWindowStart = System.currentTimeMillis();
            }
        });
    }

    private void endRaid()
    {
        log.info("Left raid: {}", currentRaid);
        pauseOverallTimer();          // stop the clock if it was running
        currentRaid = RaidType.NONE;
        SwingUtilities.invokeLater(() -> panel.setRaid(RaidType.NONE, config.dpsMode()));
    }

    /**
     * Full reset — clears everything including the persisted boss records.
     * Called on new raid entry, plugin shutdown, and the panel Reset button.
     */
    public void hardReset()
    {
        damageByNpc.clear();
        npcKeys.clear();
        bossFirstHitTime.clear();
        bossRecords.clear();
        overallTotalDamage = 0;
        overallAccumulatedMs = 0;
        overallCombatWindowStart = -1;
        SwingUtilities.invokeLater(() -> panel.reset());

        // Repopulate npcKeys from currently alive NPCs — must run on client thread
        if (currentRaid != RaidType.NONE)
        {
            clientThread.invokeLater(() ->
            {
                if (client.getNpcs() == null) return;
                for (NPC npc : client.getNpcs())
                {
                    if (npc == null) continue;
                    if (!isTrackedNpc(npc)) continue;
                    String key = npcKey(npc);
                    npcKeys.put(npc.getIndex(), key);
                    damageByNpc.put(key, 0);
                }
                if (config.dpsMode() == DpsMode.RAID_OVERALL && !npcKeys.isEmpty())
                {
                    overallCombatWindowStart = System.currentTimeMillis();
                }
            });
        }
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        updateRaidType();
    }
// -------------------------------------------------------------------------
    // NPC tracking
    // -------------------------------------------------------------------------

    @Subscribe
    public void onNpcSpawned(NpcSpawned event)
    {
        if (currentRaid == RaidType.NONE) return;

        NPC npc = event.getNpc();
        if (!isTrackedNpc(npc)) return;

        String key = npcKey(npc);
        npcKeys.put(npc.getIndex(), key);
        damageByNpc.putIfAbsent(key, 0);

        // Show the NPC card immediately in the panel (damage starts at 0)
        SwingUtilities.invokeLater(() -> panel.updateLiveNpc(key, 0));

        // RAID_OVERALL: start the combat window when the first boss spawns in the room
        if (config.dpsMode() == DpsMode.RAID_OVERALL && overallCombatWindowStart == -1)
        {
            overallCombatWindowStart = System.currentTimeMillis();
            log.debug("Overall timer resumed — boss spawned: {}", key);
        }
    }

    @Subscribe
    public void onNpcDespawned(NpcDespawned event)
    {
        if (currentRaid == RaidType.NONE) return;

        NPC npc = event.getNpc();
        String key = npcKeys.remove(npc.getIndex());
        if (key == null) return;

        int myDamage = damageByNpc.getOrDefault(key, 0);

        // ---- BOSS_SPLIT: record DPS for this boss ----
        if (config.dpsMode() == DpsMode.BOSS_SPLIT && myDamage > 0)
        {
            Long firstHit = bossFirstHitTime.remove(npc.getIndex());
            long durationMs = firstHit != null
                    ? System.currentTimeMillis() - firstHit
                    : 0;

            String displayName = displayName(key);
            BossDpsRecord record = new BossDpsRecord(displayName, myDamage, durationMs);
            bossRecords.add(record);

            final List<BossDpsRecord> snapshot = new ArrayList<>(bossRecords);
            SwingUtilities.invokeLater(() -> panel.setBossRecords(snapshot));
            log.info("Boss killed: {} {} dmg in {}ms ({} dps)",
                    displayName, myDamage, durationMs, String.format("%.2f", record.getDps()));
        }

        // ---- RAID_OVERALL: pause timer if no bosses left in room ----
        if (config.dpsMode() == DpsMode.RAID_OVERALL && npcKeys.isEmpty())
        {
            pauseOverallTimer();
            log.debug("Overall timer paused — no bosses remain in room");
        }

        // Update the NPC's damage card to show it as dead
        final String finalKey = key;
        final int finalDmg = myDamage;
        SwingUtilities.invokeLater(() -> panel.onNpcDied(finalKey, finalDmg));
    }

    // -------------------------------------------------------------------------
    // Hitsplat — local player only
    // -------------------------------------------------------------------------

    @Subscribe
    public void onHitsplatApplied(HitsplatApplied event)
    {
        if (currentRaid == RaidType.NONE) return;
        if (!(event.getActor() instanceof NPC)) return;

        NPC npc = (NPC) event.getActor();
        String key = npcKeys.get(npc.getIndex());
        if (key == null) return;

        Hitsplat hitsplat = event.getHitsplat();
        if (!hitsplat.isMine()) return;   // only track our own hits

        int damage = hitsplat.getAmount();
        if (damage <= 0) return;

        // Record first-hit timestamp for BOSS_SPLIT DPS window
        bossFirstHitTime.putIfAbsent(npc.getIndex(), System.currentTimeMillis());

        // Accumulate damage
        damageByNpc.merge(key, damage, Integer::sum);
        int npcTotal = damageByNpc.get(key);

        // RAID_OVERALL accumulation
        overallTotalDamage += damage;

        // Push panel updates
        final String finalKey = key;
        final int finalNpcTotal = npcTotal;

        if (config.dpsMode() == DpsMode.BOSS_SPLIT)
        {
            SwingUtilities.invokeLater(() -> panel.updateLiveNpc(finalKey, finalNpcTotal));
        }
        else
        {
            double dps = computeOverallDps();
            final double finalDps = dps;
            SwingUtilities.invokeLater(() ->
            {
                panel.updateLiveNpc(finalKey, finalNpcTotal);
                panel.updateOverallDps(overallTotalDamage, finalDps);
            });
        }
    }

    // -------------------------------------------------------------------------
    // RAID_OVERALL helpers
    // -------------------------------------------------------------------------

    private void pauseOverallTimer()
    {
        if (overallCombatWindowStart == -1) return;
        overallAccumulatedMs += System.currentTimeMillis() - overallCombatWindowStart;
        overallCombatWindowStart = -1;
    }

    private double computeOverallDps()
    {
        long total = overallAccumulatedMs;
        if (overallCombatWindowStart != -1)
        {
            total += System.currentTimeMillis() - overallCombatWindowStart;
        }
        double seconds = total / 1000.0;
        return seconds > 0 ? overallTotalDamage / seconds : 0;
    }

    // -------------------------------------------------------------------------
    // Helpers
    // -------------------------------------------------------------------------

    private String npcKey(NPC npc)
    {
        return npc.getName() + " #" + npc.getIndex();
    }

    private String displayName(String npcKey)
    {
        int idx = npcKey.lastIndexOf(" #");
        return idx >= 0 ? npcKey.substring(0, idx) : npcKey;
    }

    private boolean isTrackedNpc(NPC npc)
    {
        if (npc.getName() == null) return false;
        int id = npc.getId();
        if (currentRaid == RaidType.COX) return CoxNpcs.isTracked(id);
        if (currentRaid == RaidType.TOB) return TobNpcs.isTracked(id);
        if (currentRaid == RaidType.TOA) return ToaNpcs.isTracked(id);
        return false;
    }
}

package com.raiddamagetracker;

public enum DpsMode
{
    BOSS_SPLIT("Per-Boss DPS"),
    RAID_OVERALL("Overall Raid DPS");

    private final String displayName;

    DpsMode(String displayName) { this.displayName = displayName; }

    public String getDisplayName() { return displayName; }

    @Override
    public String toString() { return displayName; }
}
